  part def Controller {
    in attribute io_0 : Boolean;
    in attribute io_1 : Boolean;
    in attribute io_5 : Integer;
    in attribute io_5_valid : Boolean;
    attribute lightOn : Boolean := false;
    attribute count : Integer := 0;
    attribute previousIo0 : Boolean := false;
    attribute previousIo1 : Boolean := false;
    perform action tick {
      first start;
      then if ((io_5_valid) and (true)) {
        first start;
        then if io_5 == 6 {
          first start;
          then assign lightOn := true;
          then assign count := count + 1;
        }
        then if io_5 == 5 {
          first start;
          then assign lightOn := false;
          then assign count := count + 1;
        }
        then if io_5 == 1 {
          first start;
          then assign count := count + 1;
        }
        then if io_5 == 3 {
          first start;
          then assign count := 0;
        }
      }
      then if ((io_0) and ((not previousIo0))) {
        first start;
        then assign lightOn := true;
        then assign count := count + 1;
      }
      then if ((io_1) and ((not previousIo1))) {
        first start;
        then assign lightOn := false;
        then assign count := count + 1;
      }
      then assign previousIo0 := io_0;
      then assign previousIo1 := io_1;
    }
    out attribute io_2 : Boolean = lightOn;
    out attribute io_3 : Integer = (if ((io_5_valid) and (io_5 == 1)) ? 1000 else 0);
    out attribute io_4 : Integer = count;
    out attribute serial_0_trigger : Boolean = io_5_valid;
    out attribute serial_0_value_0 : Integer = count;
    out attribute serial_0_value_1 : Integer = (if lightOn ? 1 else 0);
  }
  part system : Controller;
}
